System.Collections.IEnumerator Check() {
 var rig=UnityEngine.Object.FindObjectOfType<Character.Control.PaddleCharacterVisual>();
 if(!rig)throw new System.Exception("No rig in live scene");
 foreach(var a in rig.GetComponentsInChildren<Character.Control.ArmsSimulation>())a.enabled=false;
 foreach(var t in UnityEngine.Object.FindObjectsOfType<Character.Control.TargetMovement>())t.enabled=false;
 foreach(var rb in rig.GetComponentsInChildren<UnityEngine.Rigidbody2D>()){rb.velocity=UnityEngine.Vector2.zero;rb.angularVelocity=0;rb.simulated=false;}
 foreach(var c in UnityEngine.Object.FindObjectsOfType<Cinemachine.CinemachineVirtualCamera>())c.enabled=false;
 var cam=UnityEngine.Camera.main; cam.orthographicSize=2.7f;cam.transform.position=rig.body.position+new UnityEngine.Vector3(0,.3f,-10);
 string log="";
 for(int i=0;i<8;i++){
  float angle=i*45; var q=UnityEngine.Quaternion.Euler(0,0,angle);
  rig.tool.rotation=q;rig.tool.position=rig.body.position+q*new UnityEngine.Vector3(1.05f,.074f,0);
  rig.Pose();yield return null;
  log+=angle+" hand error="+rig.HandError+"\n";
  UnityEngine.ScreenCapture.CaptureScreenshot(System.IO.Path.GetFullPath("scripts/player-art-20261111/pose-"+i+".png"));
  yield return new UnityEngine.WaitForEndOfFrame();yield return null;
 }
 System.IO.File.WriteAllText("scripts/player-art-20261111/poses.txt",log);
 UnityEngine.Debug.Log(log);
}
return Check();
